        const options = c.colors.filter((col) => col !== run.color);
        run.color = options[rng.int(0, options.length - 1)];
        run.left = rng.int(s.runMin, s.runMax);
      }
      run.left -= 1;
      if (lane === barrierLane) {
        state.items.push({ id: state.nextId++, kind: 'barrier', lane, z });
      } else if (rng.float() < s.gemChance) {
        state.items.push({ id: state.nextId++, kind: 'gem', lane, z, color: run.color });
        gemsInRow += 1;
      }
    }
    // Never an empty row: the centre-most free lane always gets its gem.
    if (gemsInRow === 0) {
      const lane = barrierLane === 1 ? 0 : 1;
      state.items.push({ id: state.nextId++, kind: 'gem', lane, z, color: state.laneRuns[lane].color });
    }
    state.nextRowZ += s.rowSpacingM;
  }
  state.seed = rng.seed;
}

/** A compact summary for telemetry and the end screen. */
export function summary(state) {
  return {
    score: state.score, distance: Math.round(state.distance), timeMs: Math.round(state.timeMs),
    matches: state.matches, maxChains: state.maxChains, gems: state.gems, stumbles: state.stumbles,
    cause: state.cause,
  };
}

