const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

/** Day → dusk → day over 3,600 m; dusk is reached at 1,800 m. */
export function duskAmount(distance) {
  return (1 - Math.cos((2 * Math.PI * distance) / 3600)) / 2;
