let palette = DAY, dusk = 0;
const art = loadSprites();
const coast = () => art.img('backdrop') !== null;
// Roadside props (Coral Coast): placed every PROP_M metres on alternating sides, chosen by hash.
const PROP_M = 7;
const PROPS = [
  { name: 'palm', h: 330, off: [1.95, 2.6] }, { name: 'coral', h: 95, off: [1.75, 2.3] },
  { name: 'lamp', h: 210, off: [1.7, 1.8] }, { name: 'palm', h: 300, off: [2.2, 3.0] },
  { name: 'hut', h: 210, off: [2.4, 2.9] }, { name: 'buoy', h: 85, off: [2.6, 3.4] }, { name: 'coral', h: 80, off: [2.0, 2.8] },
];
const hash = (n) => { let x = (n * 2654435761) >>> 0; x ^= x >>> 15; x = Math.imul(x, 2246822519) >>> 0; return (x ^ (x >>> 13)) >>> 0; };

function resize() {
  const r = canvas.getBoundingClientRect();
  dpr = Math.min(2, window.devicePixelRatio || 1);
  canvas.width = Math.round(r.width * dpr);
  canvas.height = Math.round(r.height * dpr);
}

const proj = (mz) => { const s = 1 / mz; return { y: HOR + (NEAR - HOR) * s, s }; };
const laneX = (lane, s) => W / 2 + (lane - 1) * (HALF * 2 / 3) * s;
const mzOf = (state, z) => RUNNER_MZ + (z - state.distance) / M_PER_UNIT;

function setPalette(distance) {
  dusk = coast() ? 0 : ease(duskAmount(distance));
  const p = {};
  for (const k of Object.keys(DAY)) p[k] = mix(DAY[k], DUSK[k], dusk);
  palette = p;
  return dusk;
}

function sky() {
  const bd = art.img('backdrop');
