// OutRun-style raster road: one textured scanline per screen row, depth from a 1/z table.
function rasterRoad(state, tex) {
  const tw = tex.naturalWidth, th = tex.naturalHeight;
  const PX_PER_M = th / 18;                 // the texture repeats every 18 m of road
  const beachY = HOR + 26;                  // sea from the painting shows down to here
  for (let y = Math.floor(HOR) + 1; y < H; y += 1) {
    const sc = (y - HOR) / (NEAR - HOR), mz = 1 / sc;
    const z = state.distance + (mz - RUNNER_MZ) * M_PER_UNIT;
    const hw = HALF * sc;
    if (y > beachY) {
      // Sand beside the boardwalk, with soft bands that rush past.
      // Wet sand near the foam line, dry sand nearer the camera; soft bands only up close (no far aliasing).
      const near = clamp((y - beachY) / 160, 0, 1);
      const band = sc > 0.25 && Math.floor(z / 5) % 2 === 0 ? 6 : 0;
      ctx.fillStyle = `rgb(${Math.round(214 + 28 * near - band)},${Math.round(196 + 24 * near - band)},${Math.round(156 + 10 * near - band)})`;
      ctx.fillRect(0, y, W, 1.6);
    }
    const v = (((z * PX_PER_M) % th) + th) % th;
    ctx.drawImage(tex, 0, Math.floor(v), tw, 1, W / 2 - hw * 1.04, y, hw * 2.08, 1.6);
  }
  // Foam line where the sea meets the beach, then a haze over the far road (atmospheric perspective).
  ctx.save();
  ctx.fillStyle = 'rgba(255,255,255,.75)'; ctx.fillRect(0, beachY, W, 2);
  const g = ctx.createLinearGradient(0, HOR, 0, HOR + 70);
  g.addColorStop(0, 'rgba(225,245,255,.7)'); g.addColorStop(1, 'rgba(225,245,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, HOR, W, 70);
  // Side shading of the road surface, darker toward the curbs (fake ambient occlusion).
  ctx.restore();
  // Curbs and lane grooves.
  const f = proj(40), n = proj(0.95);
  ctx.save();
  for (const k of [-1.04, -1 / 3, 1 / 3, 1.04]) {
    const edge = Math.abs(k) > 1;
    ctx.strokeStyle = edge ? '#ffffff' : 'rgba(150,110,60,.35)';
    ctx.lineWidth = edge ? 4 : 2;
    ctx.shadowColor = edge ? 'rgba(80,190,255,.9)' : 'transparent'; ctx.shadowBlur = edge ? 8 : 0;
    ctx.beginPath(); ctx.moveTo(W / 2 + HALF * f.s * k, f.y); ctx.lineTo(W / 2 + HALF * n.s * k, n.y); ctx.stroke();
  }
  ctx.restore();
}

function prop(state, p, mz, def, side, k) {
  const im = art.img(def.name); if (!im) return;
  const span = def.off[1] - def.off[0];
  const off = (def.off[0] + span * ((hash(k + 7) % 100) / 100)) * side;
  const x = W / 2 + off * (HALF * 2 / 3) * p.s;
  const h = def.h * p.s * (0.85 + (hash(k + 3) % 30) / 100), w = h * im.naturalWidth / im.naturalHeight;
  const fade = clamp((40 - mz) / 8, 0, 1);
  ctx.save(); ctx.globalAlpha = fade;
  if (side < 0 && def.name !== 'hut') { ctx.translate(x, 0); ctx.scale(-1, 1); ctx.translate(-x, 0); }
  ctx.fillStyle = 'rgba(60,40,10,.22)';
  ctx.beginPath(); ctx.ellipse(x, p.y, w * 0.38, w * 0.08, 0, 0, Math.PI * 2); ctx.fill();
  ctx.drawImage(im, x - w / 2, p.y - h * 0.97, w, h);
  ctx.restore();
}

