        ctx.beginPath(); ctx.ellipse(x, p.y, r * 0.7, r * 0.2, 0, 0, Math.PI * 2); ctx.fill(); ctx.globalAlpha = 1;
        gem(it.color, x, p.y - floatPx + bob, r, fade, mz < 14);""")
