function canSkipGem(state, it, speed) {
  if (state.jumpMs === null) return false;
  const c = state.config;
  const skipH = c.gem ? c.gem.skipHeightM : 1.25;
  if (state.jumpY >= skipH) return true;
  const dtSinceEntry = Math.max(0, (state.distance - it.z) / speed);
  const g = c.jump.gravity * (state.drop ? c.jump.dropGravityFactor : 1);
  const hAtZ = state.jumpY - state.jumpV * dtSinceEntry - 0.5 * g * dtSinceEntry * dtSinceEntry;
  return hAtZ >= skipH;
}

function canClearBarrier(state, it, speed) {
  if (state.jumpMs === null) return false;
  const c = state.config;
  const targetH = c.barrier ? c.barrier.heightM : c.jump.clearHeight;
  if (state.jumpY >= targetH) return true;

  const len = c.barrier ? c.barrier.lengthM : 1.2;
  const g = c.jump.gravity * (state.drop ? c.jump.dropGravityFactor : 1);
  const dtRemaining = Math.max(0, (it.z + len - state.distance) / speed);

  // Height at exit of barrier
  const hExit = state.jumpY + state.jumpV * dtRemaining - 0.5 * g * dtRemaining * dtRemaining;
  if (hExit >= targetH) return true;

