65:test('A tap (jump + immediate jumpRelease) does NOT skip a gem placed at the tap\'s peak distance', () => {
test('A tap (jump + immediate jumpRelease) does NOT skip a gem placed at the tap\'s peak distance', () => {
  let s = quiet();
  // Tap peak distance at 15 m/s is ~3.8m
  const gemZ = 3.8;
  s.items = [{ id: 43, kind: 'gem', lane: s.lane, z: gemZ, color: 'leaf' }];

  s = step(s, { type: 'jump' }).state;
  s = tick(s, DT).state;
  s = step(s, { type: 'jumpRelease' }).state;

  const events = [];
  while (s.distance < gemZ + 2 && !s.over) {
    const r = tick(s, DT);
    s = r.state;
    events.push(...r.events);
  }

  assert.equal(s.gems, 1, 'gem was collected');
  assert.deepEqual(s.chain, { color: 'leaf', count: 1 }, 'chain has the leaf gem');
  assert.ok(events.some((e) => e.type === 'collect' && e.color === 'leaf'), 'emitted collect event');
  assert.ok(!events.some((e) => e.type === 'skip'), 'no skip event emitted on tap');
});

test('Chain survives a skip: collect ember ×2, skip a tide gem by jumping, collect ember → chain is ember ×3', () => {
  let s = quiet();

  // 1. Collect ember x 2
  s.items = [
    { id: 1, kind: 'gem', lane: s.lane, z: 2, color: 'ember' },
    { id: 2, kind: 'gem', lane: s.lane, z: 5, color: 'ember' },
  ];

