test('jumping at a gem skips it even when it is further than the airtime covers (perspective reach)', () => {
  let s = quiet();
  const gemZ = s.distance + 13;                       // ~7 m airtime reach at base speed, so she lands first
  s.items = [{ id: 77, kind: 'gem', lane: s.lane, z: gemZ, color: 'tide' }];
  s = step(s, { type: 'jump' }).state;
  const events = [];
  while (s.distance < gemZ + 2 && !s.over) { const r = tick(s, DT); s = r.state; events.push(...r.events); }
  assert.equal(s.gems, 0, 'the targeted gem was not collected');
  assert.ok(events.some((e) => e.type === 'skip' && e.id === 77));
  assert.ok(events.some((e) => e.type === 'land'), 'she landed before reaching it');
});

test('only the nearest gem ahead is targeted: the next one after it is collected on the ground', () => {
  let s = quiet();
  s.items = [
